  /**
   * allSlots iterates over GET /v2/zimbra/platform/{platformId}/slot (List slots).
   *
   * It yields one item at a time, and gets the next page only when the loop reaches it. An
   * error is thrown and stops the loop.
   *
   * Returns the account slots of the platform with their offer, billing status and linked email
   * account. Filter them by `accountId`, `email`, `offer`, `billingStatus` or `used`.
   *
   * Requires the IAM action zimbra:apiovh:platform/slot/get.
   *
   * @param platformId - Platform ID
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.ZimbraSlotResponse}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.zimbra.allSlots(platformId)) console.log(item);
   */
  allSlots(
    platformId: string,
    params?: {
      /** Filter by account identifier of the slots */
      accountId?: string | undefined;
      /** Filter by the billing status of the slots */
      billingStatus?: string | undefined;
      /** Filter slot by an email */
      email?: string | undefined;
      /** Filter by offer of the slots */
      offer?: string | undefined;
      /** Filter by the empty account id of the slots */
      used?: boolean | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.ZimbraSlotResponse> {
    return this._pages(
      OPS.allSlots,
      {
        path: { platformId: platformId },
        query: [
          ["accountId", params?.accountId],
          ["billingStatus", params?.billingStatus],
          ["email", params?.email],
          ["offer", params?.offer],
          ["used", params?.used],
        ],
      },
      options,
    );
  }

